# -*- coding: utf-8 -*-
import os
import csv
import re

from .exceptions import FrequencyNotSupported, BandNotSupported


class NrarfcnCounter(object):

    nrarfcn_formulas = {
        (0, 3001): lambda freq: int((freq * 1000) / 5),
        (3001, 24251): lambda freq: int(600000 + ((freq - 3000) * 1000) / 15),
        (24251, 100000): lambda freq: int(2016667 + ((freq - 24250.08) * 1000 / 60))
    }

    def __init__(self, du_list):
        self.du_list = du_list

    def get_nrarfcns(self):
        """REMINDER: only RU in TDD mode supported"""
        _SRC_DIR = os.path.dirname(os.path.abspath(__file__))
        band_path = os.path.join(_SRC_DIR, os.path.join('data', 'band_list.csv'))
        ru_path = os.path.join(_SRC_DIR, os.path.join('data', 'ru_list.csv'))
        ru_rejected_path = os.path.join(_SRC_DIR, os.path.join('data', 'ru_list_rejected.csv'))
        band_nrarfcn = self._get_band_frequency_dict(band_path)
        ru_dict = self._parse_data(ru_path)
        ru_rejected_dict = self._parse_data(ru_rejected_path)
        ru_dict.update(ru_rejected_dict)
        tdd_rus = self._filter_for_tdds(ru_dict)

        return self._get_nrarfcns(tdd_rus, band_nrarfcn)

    def _get_nrarfcns(self, tdd_rus, band_frequency):

        if self.du_list:
            nrarfcns = {}
            for index, du in enumerate(self.du_list, start=1):
                key = "NRDU-" + str(index)
                band = self._get_band(du, tdd_rus, band_frequency)
                nrarfcns[key] = self._calculate_nrarfcn(band_frequency.get(band))
            return nrarfcns

    @staticmethod
    def _get_band(du, tdd_rus, band_frequency):
        if du.rus is not None:
            radio_type = du.rus[0].radio_type
            if radio_type is None:
                raise AttributeError('Ru in testline object has no radio type.')
            ru_info = tdd_rus.get(radio_type)
            if ru_info is not None:
                band_index = 7
                bands = ru_info[band_index].split('/')
                for band in bands:
                    band = band.strip()
                    if band in band_frequency:
                        return band
                raise BandNotSupported('No support for band {}'.format(bands[0]))

    def _get_band_frequency_dict(self, band_path):
        pattern = re.compile(r'^(\d+)MHz–(\d+)MHz$')
        band_dict = self._parse_data(band_path)
        band_tdds = self._filter_for_tdds(band_dict)

        band_frequency = {band: params[0] for band, params in band_tdds.items()}
        for band, frequency_range in band_frequency.items():
            down, up = pattern.findall(frequency_range)[0]
            band_frequency[band] = (int(down) + int(up)) // 2
        return band_frequency

    def _calculate_nrarfcn(self, frequency):
        if frequency is None:
            return None
        for freq_range, formula in self.nrarfcn_formulas.items():
            min_freq, max_freq = freq_range
            if min_freq < frequency < max_freq:
                return formula(frequency)
        error_msg = "Frequency {} outside of supported range (0 - 100000)".format(frequency)
        raise FrequencyNotSupported(error_msg)

    @staticmethod
    def _filter_for_tdds(collection):
        # support for TDD mode only
        return {key: spec for key, spec in collection.items() if "TDD" in spec}

    @staticmethod
    def _parse_data(source_file):
        with open(source_file, encoding='utf-8') as csvfile:
            data = csv.reader(csvfile, delimiter=';')
            return {specification[0]: specification[1:] for specification in data}
